-- =============================================================================================
-- Hand-written below this line: asset and schedule checks; assets at exactly one active place,
-- retired for good and only once nothing is open or scheduled; schedules only on assets in use;
-- work orders on an asset are where the asset is, and a schedule raises at most one work order per
-- due date; asset and schedule links never change. See docs/architecture/DATA_MODEL.md section 9.
-- =============================================================================================

ALTER TABLE "assets" ADD CONSTRAINT "assets_one_location"
  CHECK (num_nonnulls("unit_id", "common_area_id") = 1);
ALTER TABLE "assets" ADD CONSTRAINT "assets_text"
  CHECK ("tag" ~ '^[A-Z0-9][A-Z0-9.-]{0,29}$'
         AND "name" = btrim("name") AND length("name") BETWEEN 1 AND 120
         AND ("manufacturer" IS NULL OR ("manufacturer" = btrim("manufacturer") AND length("manufacturer") BETWEEN 1 AND 120))
         AND ("model" IS NULL OR ("model" = btrim("model") AND length("model") BETWEEN 1 AND 120))
         AND ("serial_number" IS NULL OR ("serial_number" = btrim("serial_number") AND length("serial_number") BETWEEN 1 AND 120))
         AND ("notes" IS NULL OR ("notes" = btrim("notes") AND length("notes") BETWEEN 1 AND 2000))
         AND ("status_note" IS NULL OR ("status_note" = btrim("status_note") AND length("status_note") BETWEEN 1 AND 1000)));
ALTER TABLE "assets" ADD CONSTRAINT "assets_status"
  CHECK (("status" = 'RETIRED') = ("retired_at" IS NOT NULL)
         AND ("status" = 'ACTIVE' OR "status_note" IS NOT NULL));

CREATE FUNCTION app_asset_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'ACTIVE' THEN
      RAISE EXCEPTION 'assets start in use' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."retired_at" := NULL;
  ELSE
    IF OLD."status" = 'RETIRED' THEN
      RAISE EXCEPTION 'asset % is retired and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW."organisation_id", NEW."property_id", NEW."tag", NEW."created_at")
       IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."tag", OLD."created_at") THEN
      RAISE EXCEPTION 'asset % keeps its property and tag', OLD."id" USING ERRCODE = 'check_violation';
    END IF;
    NEW."retired_at" := OLD."retired_at";
    IF NEW."status" = 'RETIRED' THEN
      IF EXISTS (SELECT 1 FROM "maintenance_schedules" WHERE "asset_id" = OLD."id" AND "active") THEN
        RAISE EXCEPTION 'pause the schedules of this asset before retiring it' USING ERRCODE = 'check_violation';
      END IF;
      IF EXISTS (SELECT 1 FROM "work_orders" WHERE "asset_id" = OLD."id" AND "status" NOT IN ('COMPLETED', 'CANCELLED')) THEN
        RAISE EXCEPTION 'finish or cancel the open work on this asset before retiring it' USING ERRCODE = 'check_violation';
      END IF;
      NEW."retired_at" := now();
    END IF;
    IF NEW."status" = 'ACTIVE' THEN
      NEW."status_note" := NULL;
    END IF;
    IF (NEW."unit_id", NEW."common_area_id") IS NOT DISTINCT FROM (OLD."unit_id", OLD."common_area_id")
       AND NEW."supplier_vendor_id" IS NOT DISTINCT FROM OLD."supplier_vendor_id" THEN
      RETURN NEW;
    END IF;
  END IF;
  PERFORM app_maintenance_location_active(NEW."property_id", NEW."unit_id", NEW."common_area_id");
  IF NEW."supplier_vendor_id" IS NOT NULL
     AND EXISTS (SELECT 1 FROM "vendors" WHERE "id" = NEW."supplier_vendor_id" AND "status" = 'ARCHIVED') THEN
    RAISE EXCEPTION 'the supplier is archived' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "assets_guard"
  BEFORE INSERT OR UPDATE ON "assets"
  FOR EACH ROW EXECUTE FUNCTION app_asset_guard();

ALTER TABLE "maintenance_schedules" ADD CONSTRAINT "maintenance_schedules_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 120
         AND ("description" IS NULL OR ("description" = btrim("description") AND length("description") BETWEEN 1 AND 2000)));
ALTER TABLE "maintenance_schedules" ADD CONSTRAINT "maintenance_schedules_interval"
  CHECK ("interval_count" BETWEEN 1 AND 366 AND "lead_days" BETWEEN 0 AND 90);

CREATE FUNCTION app_schedule_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW."created_at" := now();
  ELSIF (NEW."organisation_id", NEW."property_id", NEW."asset_id", NEW."created_by_user_id", NEW."created_at")
        IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."asset_id", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'schedule % stays on its asset', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."active" AND EXISTS (SELECT 1 FROM "assets" WHERE "id" = NEW."asset_id" AND "status" = 'RETIRED') THEN
    RAISE EXCEPTION 'the asset is retired' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."vendor_id" IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW."vendor_id" IS DISTINCT FROM OLD."vendor_id")
     AND EXISTS (SELECT 1 FROM "vendors" WHERE "id" = NEW."vendor_id" AND "status" = 'ARCHIVED') THEN
    RAISE EXCEPTION 'the vendor is archived' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "maintenance_schedules_guard"
  BEFORE INSERT OR UPDATE ON "maintenance_schedules"
  FOR EACH ROW EXECUTE FUNCTION app_schedule_guard();

ALTER TABLE "work_orders" ADD CONSTRAINT "work_orders_schedule"
  CHECK (("schedule_id" IS NULL) = ("scheduled_for" IS NULL)
         AND ("schedule_id" IS NULL OR "asset_id" IS NOT NULL));

-- Work on an asset is where the asset is; scheduled work is on the schedule's asset. Links never change.
CREATE FUNCTION app_work_order_asset_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  a record;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF (NEW."asset_id", NEW."schedule_id", NEW."scheduled_for")
       IS DISTINCT FROM (OLD."asset_id", OLD."schedule_id", OLD."scheduled_for") THEN
      RAISE EXCEPTION 'work order % keeps its asset and schedule', OLD."id" USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW."asset_id" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT "unit_id", "common_area_id", "status" INTO a FROM "assets" WHERE "id" = NEW."asset_id";
  IF a."status" = 'RETIRED' THEN
    RAISE EXCEPTION 'the asset is retired' USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."unit_id", NEW."common_area_id") IS DISTINCT FROM (a."unit_id", a."common_area_id") THEN
    RAISE EXCEPTION 'work on an asset is where the asset is' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."schedule_id" IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM "maintenance_schedules" WHERE "id" = NEW."schedule_id" AND "asset_id" = NEW."asset_id") THEN
    RAISE EXCEPTION 'scheduled work is on the schedule''s asset' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "work_orders_asset_check"
  BEFORE INSERT OR UPDATE ON "work_orders"
  FOR EACH ROW EXECUTE FUNCTION app_work_order_asset_check();

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['assets', 'maintenance_schedules'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "assets", "maintenance_schedules" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "assets", "maintenance_schedules" TO veyra_app;
